// PoolDump represents the state snapshot of a connection pool.
type PoolDump struct {
	RemoteService string
	PoolSize      uint32
	Addresses     []AddressDump
}

// AddressDump represents connection state for a specific address.
type AddressDump struct {
	Address        string
	TotalConns     int
	ActiveConns    int
	InactiveConns  int
	CurrentIndex   uint32
}

// Dump returns a snapshot of the current connection pool state for debugging and monitoring.
// It provides information about all addresses, connection counts, and their active status.
func (p *connPool) Dump() *PoolDump {
	dump := &PoolDump{
		RemoteService: p.remoteService,
		PoolSize:      p.size,
		Addresses:     make([]AddressDump, 0),
	}

	p.conns.Range(func(key, value interface{}) bool {
		addr := key.(string)
		trans := value.(*transports)

		addrDump := AddressDump{
			Address:      addr,
			TotalConns:   int(trans.size),
			CurrentIndex: atomic.LoadUint32(&trans.index),
		}

		for i := 0; i < int(trans.size); i++ {
			cliTransport := trans.cliTransports[i]
			if cliTransport != nil {
				if cliTransport.(grpc.IsActive).IsActive() {
					addrDump.ActiveConns++
				} else {
					addrDump.InactiveConns++
				}
			}
		}

		dump.Addresses = append(dump.Addresses, addrDump)
		return true
	})

	return dump
}

// newTLSConn constructs a client-side TLS connection and performs handshake.
func newTLSConn(conn net.Conn, tlsCfg *tls.Config) (net.Conn, error) {
	tlsConn := tls.Client(conn, tlsCfg)
	if err := tlsConn.Handshake(); err != nil {
		return nil, err
	}
	return tlsConn, nil
}

