	MaxReadSize      uint32
	LastHeaderStream uint32
	HasLastFrame     bool
	LastFrameType    http2.FrameType
}

// GetFrameStats returns current framer statistics for monitoring and debugging.
func (fr *Framer) GetFrameStats() FrameStats {
	stats := FrameStats{
		MaxReadSize:      fr.maxReadSize,
		LastHeaderStream: fr.lastHeaderStream,
		HasLastFrame:     fr.lastFrame != nil,
	}
	if fr.lastFrame != nil {
		stats.LastFrameType = fr.lastFrame.Header().Type
	}
	return stats
}

